db = db.getSiblingDB("gym_db");

// Q1  Selection: Active VIP members living in Chennai
// SQL equivalent:
//   SELECT member_id, name, end_date FROM members
//   WHERE tier = 'VIP' AND status = 'active' AND city = 'Chennai'
//   ORDER BY member_id;
print("\n--- Q1 Active VIP members living in Chennai");
printjson(db.members.find(
  { "membership.type": "VIP", "membership.status": "active", "address.city": "Chennai" },
  { _id: 0, member_id: 1, name: 1, "membership.end_date": 1 }
).sort({ member_id: 1 }).toArray());

// Q2  Selection: Trainers who teach Yoga or CrossFit with at least 6 years of experience
// SQL equivalent:
//   SELECT DISTINCT t.trainer_id, t.name, t.experience_years
//   FROM trainers t JOIN trainer_specializations s ON s.trainer_id = t.trainer_id
//   WHERE s.skill IN ('Yoga', 'CrossFit') AND t.experience_years >= 6
//   ORDER BY t.experience_years DESC;
print("\n--- Q2 Trainers who teach Yoga or CrossFit with at least 6 years of experience");
printjson(db.trainers.find(
  { specialization: { "$in": ["Yoga", "CrossFit"] }, experience_years: { "$gte": 6 } },
  { _id: 0, trainer_id: 1, name: 1, specialization: 1, experience_years: 1 }
).sort({ experience_years: -1 }).toArray());

// Q3  Selection: Unpaid bills already past their due date (oldest first)
// SQL equivalent:
//   SELECT payment_id, member_name, amount, status, due_date FROM payments
//   WHERE status IN ('pending', 'overdue') AND due_date < DATE '2026-09-24'
//   ORDER BY due_date, payment_id LIMIT 8;
print("\n--- Q3 Unpaid bills already past their due date (oldest first)");
printjson(db.payments.find(
  {
    status: { "$in": ["pending", "overdue"] },
    due_date: { "$lt": ISODate("2026-09-24T00:00:00Z") }
  },
  { _id: 0, payment_id: 1, member_name: 1, amount: 1, status: 1, due_date: 1 }
).sort({ due_date: 1, payment_id: 1 }).limit(8).toArray());

// Q4  Join (inner): Active VIP members with their assigned trainer
// SQL equivalent:
//   SELECT m.member_id, m.name, t.name AS trainer, t.certification
//   FROM members m INNER JOIN trainers t ON t.trainer_pk = m.assigned_trainer_id
//   WHERE m.tier = 'VIP' AND m.status = 'active'
//   ORDER BY m.member_id LIMIT 8;
print("\n--- Q4 Active VIP members with their assigned trainer");
printjson(db.members.aggregate([
  { "$match": { "membership.type": "VIP", "membership.status": "active" } },
  {
    "$lookup": { from: "trainers", localField: "assigned_trainer_id", foreignField: "_id", as: "t" }
  },
  { "$unwind": "$t" },
  {
    "$project": { _id: 0, member_id: 1, name: 1, trainer: "$t.name", certification: "$t.certification" }
  },
  { "$sort": { member_id: 1 } },
  { "$limit": 8 }
]).toArray());

// Q5  Join (three tables): Attendance history of MEM1001 with class name and session time
// SQL equivalent:
//   SELECT s.date, c.class_name, s.start_time, a.status, a.check_in_time
//   FROM members m
//   JOIN attendance a ON a.member_id = m.member_pk
//   JOIN class_sessions s ON s.session_pk = a.session_id
//   JOIN classes c ON c.class_pk = a.class_id
//   WHERE m.member_id = 'MEM1001' ORDER BY s.date DESC;
print("\n--- Q5 Attendance history of MEM1001 with class name and session time");
printjson(db.members.aggregate([
  { "$match": { member_id: "MEM1001" } },
  { "$lookup": { from: "attendance", localField: "_id", foreignField: "member_id", as: "a" } },
  { "$unwind": "$a" },
  {
    "$lookup": { from: "class_sessions", localField: "a.session_id", foreignField: "_id", as: "s" }
  },
  { "$unwind": "$s" },
  { "$lookup": { from: "classes", localField: "a.class_id", foreignField: "_id", as: "c" } },
  { "$unwind": "$c" },
  {
    "$project": {
      _id: 0,
      date: "$s.date",
      class_name: "$c.class_name",
      start_time: "$s.start_time",
      status: "$a.status",
      check_in_time: "$a.check_in_time"
    }
  },
  { "$sort": { date: -1 } }
]).toArray());

// Q6  Join (left outer): Every trainer with the number of classes they teach, including trainers with none
// SQL equivalent:
//   SELECT t.trainer_id, t.name, COUNT(c.class_id) AS classes
//   FROM trainers t LEFT OUTER JOIN classes c ON c.trainer_id = t.trainer_pk
//   GROUP BY t.trainer_id, t.name ORDER BY classes DESC, t.trainer_id;
print("\n--- Q6 Every trainer with the number of classes they teach, including trainers with none");
printjson(db.trainers.aggregate([
  { "$lookup": { from: "classes", localField: "_id", foreignField: "trainer_id", as: "c" } },
  {
    "$project": { _id: 0, trainer_id: 1, name: 1, classes: { "$size": "$c" }, class_names: "$c.class_name" }
  },
  { "$sort": { classes: -1, trainer_id: 1 } }
]).toArray());

// Q7  Grouping and aggregation: Money collected by payment mode (COUNT, SUM, AVG)
// SQL equivalent:
//   SELECT payment_mode, COUNT(*) AS payments, SUM(amount) AS total, AVG(amount) AS average
//   FROM payments WHERE status = 'paid'
//   GROUP BY payment_mode ORDER BY total DESC;
print("\n--- Q7 Money collected by payment mode (COUNT, SUM, AVG)");
printjson(db.payments.aggregate([
  { "$match": { status: "paid" } },
  {
    "$group": {
      _id: "$payment_mode",
      payments: { "$sum": 1 },
      total: { "$sum": "$amount" },
      average: { "$avg": "$amount" }
    }
  },
  {
    "$project": {
      _id: 0,
      payment_mode: "$_id",
      payments: "$payments",
      total: "$total",
      average: { "$round": ["$average", 0] }
    }
  },
  { "$sort": { total: -1 } }
]).toArray());

// Q8  Grouping with HAVING: Cities with more than 10 members, split by tier
// SQL equivalent:
//   SELECT city, COUNT(*) AS members,
//          SUM(CASE WHEN tier = 'VIP' THEN 1 ELSE 0 END) AS vip
//   FROM members GROUP BY city HAVING COUNT(*) > 10 ORDER BY members DESC;
print("\n--- Q8 Cities with more than 10 members, split by tier");
printjson(db.members.aggregate([
  {
    "$group": {
      _id: "$address.city",
      members: { "$sum": 1 },
      basic: { "$sum": { "$cond": [{ "$eq": ["$membership.type", "Basic"] }, 1, 0] } },
      premium: { "$sum": { "$cond": [{ "$eq": ["$membership.type", "Premium"] }, 1, 0] } },
      vip: { "$sum": { "$cond": [{ "$eq": ["$membership.type", "VIP"] }, 1, 0] } }
    }
  },
  { "$match": { members: { "$gt": 10 } } },
  {
    "$project": {
      _id: 0,
      city: "$_id",
      members: "$members",
      basic: "$basic",
      premium: "$premium",
      vip: "$vip"
    }
  },
  { "$sort": { members: -1 } }
]).toArray());

// Q9  Grouping and aggregation: Attendance outcome by class category
// SQL equivalent:
//   SELECT c.category, COUNT(*) AS marked,
//          SUM(CASE WHEN a.status = 'present' THEN 1 ELSE 0 END) AS present,
//          SUM(CASE WHEN a.status = 'late' THEN 1 ELSE 0 END) AS late,
//          SUM(CASE WHEN a.status = 'absent' THEN 1 ELSE 0 END) AS absent
//   FROM attendance a JOIN classes c ON c.class_pk = a.class_id
//   GROUP BY c.category ORDER BY marked DESC;
print("\n--- Q9 Attendance outcome by class category");
printjson(db.attendance.aggregate([
  { "$lookup": { from: "classes", localField: "class_id", foreignField: "_id", as: "c" } },
  { "$unwind": "$c" },
  {
    "$group": {
      _id: "$c.category",
      marked: { "$sum": 1 },
      present: { "$sum": { "$cond": [{ "$eq": ["$status", "present"] }, 1, 0] } },
      late: { "$sum": { "$cond": [{ "$eq": ["$status", "late"] }, 1, 0] } },
      absent: { "$sum": { "$cond": [{ "$eq": ["$status", "absent"] }, 1, 0] } }
    }
  },
  {
    "$project": {
      _id: 0,
      category: "$_id",
      marked: "$marked",
      present: "$present",
      late: "$late",
      absent: "$absent"
    }
  },
  { "$sort": { marked: -1 } }
]).toArray());

// Q10  Subquery (scalar): Members whose attendance rate is below the gym-wide average
// SQL equivalent:
//   SELECT member_id, AVG(CASE WHEN status <> 'absent' THEN 100 ELSE 0 END) AS rate
//   FROM attendance GROUP BY member_id
//   HAVING rate < (SELECT AVG(CASE WHEN status <> 'absent' THEN 100 ELSE 0 END)
//                  FROM attendance)
//   ORDER BY rate LIMIT 8;
print("\n--- Q10 Members whose attendance rate is below the gym-wide average");
printjson(db.attendance.aggregate([
  { "$addFields": { attended: { "$cond": [{ "$eq": ["$status", "absent"] }, 0, 100] } } },
  {
    "$facet": {
      overall: [{ "$group": { _id: null, avg: { "$avg": "$attended" } } }],
      per_member: [
        {
          "$group": { _id: "$member_name", rate: { "$avg": "$attended" }, marked: { "$sum": 1 } }
        }
      ]
    }
  },
  { "$unwind": "$overall" },
  { "$unwind": "$per_member" },
  { "$match": { "$expr": { "$lt": ["$per_member.rate", "$overall.avg"] } } },
  {
    "$project": {
      name: "$per_member._id",
      marked: "$per_member.marked",
      rate_pct: { "$round": ["$per_member.rate", 1] },
      gym_average_pct: { "$round": ["$overall.avg", 1] }
    }
  },
  { "$project": { _id: 0 } },
  { "$sort": { rate_pct: 1, name: 1 } },
  { "$limit": 8 }
]).toArray());

// Q11  Subquery (correlated): Members with more than one unpaid bill
// SQL equivalent:
//   SELECT m.member_id, m.name,
//          (SELECT COUNT(*) FROM payments p
//           WHERE p.member_id = m.member_pk AND p.status IN ('pending','overdue')) AS unpaid
//   FROM members m
//   WHERE (SELECT COUNT(*) FROM payments p
//          WHERE p.member_id = m.member_pk AND p.status IN ('pending','overdue')) > 1
//   ORDER BY m.member_id;
print("\n--- Q11 Members with more than one unpaid bill");
printjson(db.members.aggregate([
  {
    "$lookup": {
      from: "payments",
      let: { mid: "$_id" },
      as: "unpaid",
      pipeline: [
        {
          "$match": {
            "$expr": {
              "$and": [
                { "$eq": ["$member_id", "$$mid"] },
                { "$in": ["$status", ["pending", "overdue"]] }
              ]
            }
          }
        }
      ]
    }
  },
  { "$match": { "$expr": { "$gt": [{ "$size": "$unpaid" }, 1] } } },
  {
    "$project": {
      _id: 0,
      member_id: 1,
      name: 1,
      tier: "$membership.type",
      unpaid_bills: { "$size": "$unpaid" },
      amount_due: { "$sum": "$unpaid.amount" }
    }
  },
  { "$sort": { member_id: 1 } }
]).toArray());

// Q12  Subquery (EXISTS): Classes taught by trainers who coach more than 8 members
// SQL equivalent:
//   SELECT c.class_name, c.trainer_name FROM classes c
//   WHERE EXISTS (SELECT 1 FROM members m
//                 WHERE m.assigned_trainer_id = c.trainer_id
//                 GROUP BY m.assigned_trainer_id HAVING COUNT(*) > 8);
print("\n--- Q12 Classes taught by trainers who coach more than 8 members");
printjson(db.classes.aggregate([
  {
    "$lookup": { from: "members", localField: "trainer_id", foreignField: "assigned_trainer_id", as: "m" }
  },
  { "$match": { "$expr": { "$gt": [{ "$size": "$m" }, 8] } } },
  { "$project": { _id: 0, class_name: 1, trainer_name: 1, trainer_members: { "$size": "$m" } } },
  { "$sort": { class_name: 1 } }
]).toArray());

// Q13  Set operation (UNION): Members enrolled in Morning Yoga or Evening Yoga (each counted once)
// SQL equivalent:
//   SELECT member_name FROM enrollments WHERE class_name = 'Morning Yoga'
//   UNION
//   SELECT member_name FROM enrollments WHERE class_name = 'Evening Yoga';
print("\n--- Q13 Members enrolled in Morning Yoga or Evening Yoga (each counted once)");
printjson(db.classes.aggregate([
  {
    "$facet": {
      a: [
        { "$match": { class_name: "Morning Yoga" } },
        { "$project": { n: "$enrolled_members.member_name" } }
      ],
      b: [
        { "$match": { class_name: "Evening Yoga" } },
        { "$project": { n: "$enrolled_members.member_name" } }
      ]
    }
  },
  {
    "$project": {
      morning: { "$size": { "$arrayElemAt": ["$a.n", 0] } },
      evening: { "$size": { "$arrayElemAt": ["$b.n", 0] } },
      result: { "$setUnion": [{ "$arrayElemAt": ["$a.n", 0] }, { "$arrayElemAt": ["$b.n", 0] }] }
    }
  },
  {
    "$project": {
      morning_yoga: "$morning",
      evening_yoga: "$evening",
      union_size: { "$size": "$result" },
      result: 1
    }
  }
]).toArray());

// Q14  Set operation (INTERSECT): Members enrolled in both CrossFit Burn and Strength 101
// SQL equivalent:
//   SELECT member_name FROM enrollments WHERE class_name = 'CrossFit Burn'
//   INTERSECT
//   SELECT member_name FROM enrollments WHERE class_name = 'Strength 101';
print("\n--- Q14 Members enrolled in both CrossFit Burn and Strength 101");
printjson(db.classes.aggregate([
  {
    "$facet": {
      a: [
        { "$match": { class_name: "CrossFit Burn" } },
        { "$project": { n: "$enrolled_members.member_name" } }
      ],
      b: [
        { "$match": { class_name: "Strength 101" } },
        { "$project": { n: "$enrolled_members.member_name" } }
      ]
    }
  },
  {
    "$project": {
      result: { "$setIntersection": [{ "$arrayElemAt": ["$a.n", 0] }, { "$arrayElemAt": ["$b.n", 0] }] }
    }
  },
  { "$project": { intersect_size: { "$size": "$result" }, result: 1 } }
]).toArray());

// Q15  Set operation (EXCEPT): Active members who are not enrolled in any class
// SQL equivalent:
//   SELECT name FROM members WHERE status = 'active'
//   EXCEPT
//   SELECT member_name FROM enrollments;
print("\n--- Q15 Active members who are not enrolled in any class");
printjson(db.members.aggregate([
  {
    "$facet": {
      active: [
        { "$match": { "membership.status": "active" } },
        { "$group": { _id: null, n: { "$addToSet": "$name" } } }
      ],
      enrolled: [
        {
          "$lookup": {
            from: "classes",
            localField: "_id",
            foreignField: "enrolled_members.member_id",
            as: "c"
          }
        },
        { "$match": { "$expr": { "$gt": [{ "$size": "$c" }, 0] } } },
        { "$group": { _id: null, n: { "$addToSet": "$name" } } }
      ]
    }
  },
  {
    "$project": {
      result: {
        "$setDifference": [{ "$arrayElemAt": ["$active.n", 0] }, { "$arrayElemAt": ["$enrolled.n", 0] }]
      },
      active_members: { "$size": { "$arrayElemAt": ["$active.n", 0] } },
      enrolled_somewhere: { "$size": { "$arrayElemAt": ["$enrolled.n", 0] } }
    }
  },
  {
    "$project": { active_members: 1, enrolled_somewhere: 1, except_size: { "$size": "$result" }, result: 1 }
  }
]).toArray());
